<span class="line">			<span class="token keyword">int</span> num <span class="token operator">=</span> dimension<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">*</span> dimension<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">+</span> dimension<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span> <span class="token operator">*</span> dimension<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">			<span class="token keyword">if</span> <span class="token punctuation">(</span>m1 <span class="token operator">&lt;</span> num<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">				m1 <span class="token operator">=</span> num<span class="token punctuation">;</span></span>
<span class="line">				m2 <span class="token operator">=</span> dimension<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">*</span> dimension<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">			<span class="token punctuation">}</span></span>
<span class="line">			<span class="token keyword">if</span> <span class="token punctuation">(</span>m1 <span class="token operator">==</span> num<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
